#!/usr/bin/env python3
import concurrent.futures
import ipaddress
import json
import sys
import xml.etree.ElementTree as ET

SCOPE = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = "192.168.122.1"
WORKERS = 32


def envelope_fields(envelope):
    if isinstance(envelope, str):
        try:
            envelope = json.loads(envelope)
        except Exception:
            return envelope, None, None
    if not isinstance(envelope, dict):
        return envelope, None, None
    stdout = envelope.get("stdout")
    if stdout is None and isinstance(envelope.get("streams"), dict):
        stdout = envelope["streams"].get("stdout")
    code = envelope.get("exit_code", envelope.get("returncode"))
    if code is None:
        code = envelope.get("code")
    return envelope, stdout, code


def probe(segment):
    targets = [str(addr) for addr in segment]
    targets = [addr for addr in targets if addr != EXCLUDED]
    argv = [
        "nmap", "-sn", "-PR", "-n", "-T4", "--max-retries", "1",
        "--host-timeout", "20s", "--exclude", EXCLUDED, "-oX", "-",
        *targets,
    ]
    result = {
        "segment": str(segment),
        "requested_target_count": len(targets),
        "excluded_address": EXCLUDED,
        "argv": argv,
    }
    try:
        import framework_evidence
        raw = framework_evidence.run_tool(argv)
        envelope, stdout, exit_code = envelope_fields(raw)
        result["raw_envelope"] = envelope
        result["exit_code"] = exit_code
        result["xml_valid"] = False
        result["responsive_addresses"] = []
        result["nmap_reported_total"] = None
        result["nmap_reported_up"] = None
        result["nmap_reported_down"] = None
        result["completion"] = "unverified"
        if isinstance(stdout, bytes):
            stdout = stdout.decode("utf-8", errors="replace")
        if isinstance(stdout, str) and stdout.strip():
            try:
                root = ET.fromstring(stdout)
                result["xml_valid"] = root.tag == "nmaprun"
                if root.tag == "nmaprun":
                    for host in root.findall("host"):
                        status = host.find("status")
                        if status is not None and status.get("state") == "up":
                            for address in host.findall("address"):
                                if address.get("addrtype") == "ipv4":
                                    result["responsive_addresses"].append(address.get("addr"))
                    hosts = root.find("runstats/hosts")
                    if hosts is not None:
                        for key, output_key in (("total", "nmap_reported_total"),
                                                ("up", "nmap_reported_up"),
                                                ("down", "nmap_reported_down")):
                            value = hosts.get(key)
                            if value is not None:
                                result[output_key] = int(value)
            except (ET.ParseError, ValueError):
                result["xml_parse_error"] = "Nmap stdout was not valid, complete XML."
        total = result["nmap_reported_total"]
        if exit_code == 0 and result["xml_valid"] and total == len(targets):
            result["completion"] = "complete_for_requested_targets"
        elif exit_code not in (None, 0):
            result["completion"] = "failed"
        elif result["xml_valid"] and total is not None:
            result["completion"] = "incomplete_or_count_mismatch"
        return result
    except Exception as exc:
        result["completion"] = "tool_call_error"
        result["error"] = f"{type(exc).__name__}: {exc}"
        return result


def main():
    segments = list(SCOPE.subnets(new_prefix=24))
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = {pool.submit(probe, segment): segment for segment in segments}
        for future in concurrent.futures.as_completed(futures):
            try:
                results.append(future.result())
            except Exception as exc:
                segment = futures[future]
                results.append({"segment": str(segment), "completion": "worker_error",
                                "error": f"{type(exc).__name__}: {exc}"})
    results.sort(key=lambda item: ipaddress.ip_network(item["segment"]).network_address)
    responsive = sorted({addr for item in results
                         for addr in item.get("responsive_addresses", [])},
                        key=ipaddress.ip_address)
    complete = [item["segment"] for item in results
                if item.get("completion") == "complete_for_requested_targets"]
    gaps = [item["segment"] for item in results
            if item.get("completion") != "complete_for_requested_targets"]
    report = {
        "scope": str(SCOPE),
        "method": "parallel Nmap ARP host discovery (-sn -PR), partitioned into /24 segments",
        "excluded_address": EXCLUDED,
        "parallel_workers": WORKERS,
        "segments_planned": len(segments),
        "segments_returned": len(results),
        "responsive_addresses": responsive,
        "complete_segments": complete,
        "segments_with_gaps_or_unverified_coverage": gaps,
        "coverage_note": "A segment is counted complete only when the tool reports exit code 0, stdout parses as Nmap XML, and Nmap runstats total equals the explicit requested target count. No-response findings apply only to targets in such completed probes.",
        "probes": results,
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

