import concurrent.futures
import ipaddress
import json
import re

import framework_evidence

NETWORK = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = "192.168.122.1"
WORKERS = 32


def find_value(obj, key):
    if isinstance(obj, dict):
        if key in obj:
            return obj[key]
        for value in obj.values():
            found = find_value(value, key)
            if found is not None:
                return found
    elif isinstance(obj, list):
        for value in obj:
            found = find_value(value, key)
            if found is not None:
                return found
    return None


def as_text(value):
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("text", "content", "preview"):
            if isinstance(value.get(key), str):
                return value[key]
    return ""


def probe(segment):
    targets = [str(ip) for ip in segment.hosts()]
    if EXCLUDED in targets:
        targets.remove(EXCLUDED)
    argv = [
        "nmap", "-sn", "-PR", "-n", "-T4", "--max-retries", "1",
        "--host-timeout", "20s", "-oG", "-", "--exclude", EXCLUDED,
        *targets,
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
    except Exception as exc:
        return {
            "range": str(segment),
            "requested_targets": len(targets),
            "responsive_addresses": [],
            "completed": False,
            "gap": True,
            "error": repr(exc),
            "result_envelope": None,
        }

    stdout = as_text(find_value(envelope, "stdout"))
    exit_code = find_value(envelope, "exit_code")
    if exit_code is None:
        exit_code = find_value(envelope, "returncode")
    responsive = sorted(set(re.findall(
        r"(?m)^Host:\s+((?:\d{1,3}\.){3}\d{1,3})\s+.*?Status:\s+Up\s*$",
        stdout,
    )))
    done = re.search(
        r"(?m)^# Nmap done .*?--\s+(\d+) IP addresses?\s+\((\d+) hosts? up\)",
        stdout,
    )
    scanned_count = int(done.group(1)) if done else None
    summary_up = int(done.group(2)) if done else None
    complete = (
        exit_code == 0
        and scanned_count == len(targets)
        and summary_up is not None
    )
    return {
        "range": str(segment),
        "requested_targets": len(targets),
        "nmap_reported_scanned_targets": scanned_count,
        "nmap_reported_hosts_up": summary_up,
        "responsive_addresses": responsive,
        "exit_code": exit_code,
        "completed": complete,
        "gap": not complete,
        "result_envelope": envelope,
    }


def main():
    segments = list(NETWORK.subnets(new_prefix=24))
    results = [None] * len(segments)
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        future_to_index = {
            pool.submit(probe, segment): index
            for index, segment in enumerate(segments)
        }
        for future in concurrent.futures.as_completed(future_to_index):
            index = future_to_index[future]
            try:
                results[index] = future.result()
            except Exception as exc:
                results[index] = {
                    "range": str(segments[index]),
                    "requested_targets": 255 if EXCLUDED in segments[index] else 256,
                    "responsive_addresses": [],
                    "completed": False,
                    "gap": True,
                    "error": repr(exc),
                    "result_envelope": None,
                }

    hosts = sorted({
        address
        for item in results
        for address in item.get("responsive_addresses", [])
        if address != EXCLUDED
    }, key=lambda value: int(ipaddress.ip_address(value)))
    gaps = [item["range"] for item in results if item.get("gap")]
    report = {
        "method": "parallel Nmap ARP host discovery (-sn -PR), explicit targets partitioned into /24 ranges",
        "scope": str(NETWORK),
        "excluded_address": EXCLUDED,
        "parallel_workers": WORKERS,
        "ranges_planned": len(segments),
        "ranges_completed": len(results) - len(gaps),
        "gaps": gaps,
        "responsive_addresses": hosts,
        "probes": results,
    }
    print(json.dumps(report, separators=(",", ":"), ensure_ascii=True))


if __name__ == "__main__":
    main()

