#!/usr/bin/env python3
import concurrent.futures
import json
import sys

from framework_evidence import run_tool

PORT_RANGE = "0-65535"
JOBS = [
    ("192.168.3.1", "tcp", "-sT"),
    ("192.168.0.1", "udp", "-sU"),
    ("192.168.3.1", "udp", "-sU"),
    ("192.168.65.3", "udp", "-sU"),
    ("192.168.65.6", "udp", "-sU"),
]


def emit(record):
    print(json.dumps(record, sort_keys=True, default=str), flush=True)


def scan(job):
    target, protocol, scan_type = job
    argv = [
        "nmap", "-n", "-Pn", scan_type, "-p", PORT_RANGE,
        "-T5", "--min-rate", "5000", "--max-retries", "1", "--reason",
        target,
    ]
    try:
        envelope = run_tool(argv)
        return target, protocol, argv, envelope, None
    except Exception as exc:
        return target, protocol, argv, None, repr(exc)


def completion_confirmed(envelope):
    if not isinstance(envelope, dict):
        return False
    runs = envelope.get("tool_runs")
    if not isinstance(runs, list) or not runs:
        return False
    for run in runs:
        if not isinstance(run, dict) or run.get("status") != "completed" or run.get("exit_code") != 0:
            return False
        structured = run.get("structured_output")
        if not isinstance(structured, dict) or structured.get("scan_completed") is not True:
            return False
    return True


def main():
    emit({
        "event": "scan_plan",
        "requested_port_range": PORT_RANGE,
        "parallel_scans": len(JOBS),
        "targets_protocols": [
            {"target": target, "protocol": protocol} for target, protocol, _ in JOBS
        ],
        "method_note": "TCP uses connect scan; UDP uses UDP scan. Results are emitted individually as jobs return.",
    })
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(JOBS)) as pool:
        futures = [pool.submit(scan, job) for job in JOBS]
        for future in concurrent.futures.as_completed(futures):
            target, protocol, argv, envelope, error = future.result()
            emit({
                "event": "scan_result",
                "target": target,
                "protocol": protocol,
                "requested_port_range": PORT_RANGE,
                "argv": argv,
                "coverage_confirmed": completion_confirmed(envelope),
                "error": error,
                "result": envelope,
            })


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        emit({"event": "interrupted", "coverage_note": "Any scan without a returned completed result remains unconfirmed."})
        sys.exit(130)

