import concurrent.futures
import json
import sys

from framework_evidence import run_tool

TARGET = "192.168.65.6"
BATCH_SIZE = 2048
WORKERS = 4


def scan_batch(start, end):
    argv = [
        "nmap", "-sU", "-n", "-Pn", "-T4", "--max-retries", "1",
        "--reason", "-p", f"{start}-{end}", "-oX", "-", TARGET,
    ]
    try:
        evidence = run_tool(argv)
        return {
            "target": TARGET,
            "transport": "udp",
            "requested_port_range": [start, end],
            "argv": argv,
            "evidence": evidence,
        }
    except Exception as exc:
        return {
            "target": TARGET,
            "transport": "udp",
            "requested_port_range": [start, end],
            "argv": argv,
            "execution_error": f"{type(exc).__name__}: {exc}",
        }


def main():
    ranges = [(start, min(start + BATCH_SIZE - 1, 65535))
              for start in range(0, 65536, BATCH_SIZE)]
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = [pool.submit(scan_batch, start, end) for start, end in ranges]
        for future in concurrent.futures.as_completed(futures):
            try:
                record = future.result()
            except Exception as exc:
                record = {"unexpected_worker_error": f"{type(exc).__name__}: {exc}"}
            print(json.dumps(record, ensure_ascii=False, default=str), flush=True)


if __name__ == "__main__":
    main()

