import json
import re

import framework_evidence

HOST = "192.168.3.1"
PORT = 52693


def collect_streams(value, key=""):
    found = []
    if isinstance(value, dict):
        for child_key, child in value.items():
            if child_key.lower() in ("stdout", "stderr") and isinstance(child, str):
                found.append((child_key.lower(), child))
            else:
                found.extend(collect_streams(child, child_key))
    elif isinstance(value, list):
        for child in value:
            found.extend(collect_streams(child, key))
    return found


def port_lines(envelope):
    lines = []
    for stream_name, text in collect_streams(envelope):
        if stream_name != "stdout":
            continue
        for line in text.splitlines():
            if re.search(r"\b52693/tcp\b", line):
                lines.append(line.strip())
    return lines


def needs_higher_intensity(lines):
    for line in lines:
        match = re.search(r"\b52693/tcp\s+(open(?:\|filtered)?)\s+(\S+)(.*)$", line)
        if not match:
            continue
        state, service, remainder = match.groups()
        if service.lower() in ("unknown", "tcpwrapped", "?", "-", ""):
            return True
        if not remainder.strip():
            return True
    return False


def run_scan(intensity):
    argv = [
        "nmap", "-Pn", "-n", "-sV", "--version-intensity", str(intensity),
        "--reason", "-p", str(PORT), "-oN", "-", HOST,
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
        lines = port_lines(envelope)
        return {"argv": argv, "envelope": envelope, "matching_port_lines": lines}
    except Exception as exc:
        return {"argv": argv, "execution_error": repr(exc), "matching_port_lines": []}


first = run_scan(7)
results = [first]
if needs_higher_intensity(first.get("matching_port_lines", [])):
    results.append(run_scan(9))

final_lines = results[-1].get("matching_port_lines", [])
if final_lines:
    classification = "port line observed; interpret state and service/version from the retained raw evidence"
elif results[-1].get("execution_error"):
    classification = "execution limitation; service remains unknown"
else:
    classification = "no matching port line in captured stdout; state and service remain unknown"

print(json.dumps({
    "target": HOST,
    "protocol": "TCP",
    "port": PORT,
    "classification": classification,
    "passes": results,
    "limitations": "Only this TCP port was probed. A missing or truncated response is not evidence that the service is absent; Nmap output and execution status must be assessed from each retained envelope."
}, ensure_ascii=False, indent=2, default=str))

