import json
import re

import framework_evidence

HOST = "192.168.65.3"
PORTS = (111, 54755)


def envelope_text(value):
    """Collect stdout text from the helper envelope without discarding the envelope."""
    chunks = []
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "stdout" and isinstance(child, str):
                chunks.append(child)
            elif isinstance(child, (dict, list)):
                chunks.extend(envelope_text(child))
    elif isinstance(value, list):
        for child in value:
            chunks.extend(envelope_text(child))
    return chunks


def observed_lines(envelope, port):
    text = "\n".join(envelope_text(envelope))
    pattern = re.compile(r"^\s*" + re.escape(str(port)) + r"/udp\s+.*$", re.IGNORECASE)
    return [line.strip() for line in text.splitlines() if pattern.match(line)]


def needs_higher_intensity(lines):
    if not lines:
        return True
    for line in lines:
        match = re.match(r"\d+/udp\s+(\S+)(?:\s+(.*))?$", line, re.IGNORECASE)
        if not match:
            return True
        state = match.group(1).lower()
        service_details = (match.group(2) or "").strip()
        service_name = service_details.split(None, 1)[0].lower() if service_details else ""
        if state == "open|filtered" or state != "open" or service_name in ("", "unknown", "tcpwrapped"):
            return True
    return False


records = []
initial_argv = [
    "nmap", "-sU", "-sV", "--version-intensity", "7",
    "-p", "U:111,54755", HOST,
]
try:
    initial = framework_evidence.run_tool(initial_argv)
    records.append({"phase": "initial_service_identification", "argv": initial_argv, "envelope": initial})
except Exception as exc:
    initial = None
    records.append({"phase": "initial_service_identification", "argv": initial_argv,
                    "execution_error": repr(exc)})

port_results = []
for port in PORTS:
    lines = observed_lines(initial, port) if initial is not None else []
    ambiguous = needs_higher_intensity(lines)
    higher_lines = []
    if ambiguous:
        argv = ["nmap", "-sU", "-sV", "--version-intensity", "9", "-p", "U:" + str(port), HOST]
        try:
            envelope = framework_evidence.run_tool(argv)
            records.append({"phase": "higher_intensity_service_identification", "port": port,
                            "argv": argv, "envelope": envelope})
            higher_lines = observed_lines(envelope, port)
        except Exception as exc:
            records.append({"phase": "higher_intensity_service_identification", "port": port,
                            "argv": argv, "execution_error": repr(exc)})

    final_lines = higher_lines if higher_lines else lines
    if not final_lines:
        classification = "unknown; no usable port-specific service line was captured"
        limitation = "No matching Nmap output line was available; this does not establish that the service is absent."
    else:
        states = [re.match(r"\d+/udp\s+(\S+)", line, re.IGNORECASE) for line in final_lines]
        state_names = [m.group(1).lower() for m in states if m]
        if any(state == "open|filtered" for state in state_names):
            classification = "ambiguous UDP response; open|filtered is not a confirmed service identity"
            limitation = "UDP response state is inconclusive; retain the exact Nmap line as evidence."
        elif any(needs_higher_intensity([line]) for line in final_lines):
            classification = "unknown or ambiguous service identity"
            limitation = "No confirmed service identity was extracted; the exact observed line is retained."
        else:
            classification = "service identified by Nmap output; assess the exact line for version detail"
            limitation = "Nmap's reported label is evidence, not independent confirmation; any absent version detail remains unknown."
    port_results.append({
        "host": HOST,
        "port": port,
        "protocol": "udp",
        "initial_service_lines": lines,
        "higher_intensity_attempted": ambiguous,
        "higher_intensity_service_lines": higher_lines,
        "classification": classification,
        "limitations": limitation,
    })

print(json.dumps({
    "target": HOST,
    "scope": {"protocol": "udp", "ports": list(PORTS)},
    "port_results": port_results,
    "tool_observations": records,
}, ensure_ascii=False))

