import concurrent.futures
import json
import xml.etree.ElementTree as ET

import framework_evidence

EXCLUDED = "192.168.122.1"
PREVIOUSLY_OBSERVED = {
    "192.168.0.1",
    "192.168.0.5",
    "192.168.3.1",
    "192.168.65.3",
    "192.168.65.6",
}
BASE = [
    "nmap", "-n", "-T4", "--min-rate", "10000", "--max-retries", "1",
    "--initial-rtt-timeout", "200ms", "--max-rtt-timeout", "1000ms",
    "--exclude", EXCLUDED, "-oX", "-",
]


def envelope_strings(value):
    if isinstance(value, str):
        text = value.strip()
        if "<nmaprun" in text or text.startswith("<?xml"):
            yield text
        else:
            try:
                yield from envelope_strings(json.loads(value))
            except Exception:
                pass
    elif isinstance(value, dict):
        for child in value.values():
            yield from envelope_strings(child)
    elif isinstance(value, (list, tuple)):
        for child in value:
            yield from envelope_strings(child)


def xml_roots(envelope):
    for text in envelope_strings(envelope):
        start = text.find("<?xml")
        if start < 0:
            start = text.find("<nmaprun")
        if start < 0:
            continue
        candidate = text[start:]
        try:
            yield ET.fromstring(candidate)
        except Exception:
            # Tool output may wrap or truncate XML; preserve it in the envelope.
            continue


def responsive_hosts(envelope):
    found = set()
    for root in xml_roots(envelope):
        for host in root.findall("host"):
            if host.find("status") is None or host.find("status").get("state") != "up":
                continue
            for address in host.findall("address"):
                if address.get("addrtype") == "ipv4" and address.get("addr"):
                    found.add(address.get("addr"))
    return found


def invoke(argv):
    try:
        result = framework_evidence.run_tool(argv)
        return {"command": argv, "result": result}
    except Exception as exc:
        return {"command": argv, "execution_error": repr(exc)}


def completion_evidence(envelope, protocol):
    evidence = {"xml_found": False, "scaninfo": [], "runstats_finished": None,
                "port_observations": []}
    for root in xml_roots(envelope):
        evidence["xml_found"] = True
        for info in root.findall("scaninfo"):
            if info.get("protocol") == protocol:
                evidence["scaninfo"].append({
                    "protocol": info.get("protocol"),
                    "type": info.get("type"),
                    "services": info.get("services"),
                    "numservices": info.get("numservices"),
                })
        finished = root.find("./runstats/finished")
        if finished is not None:
            evidence["runstats_finished"] = {
                "exit": finished.get("exit"),
                "summary": finished.get("summary"),
            }
        for host in root.findall("host"):
            for port in host.findall("./ports/port"):
                state_node = port.find("state")
                service_node = port.find("service")
                if state_node is None:
                    continue
                state = state_node.get("state")
                # Retain open and ambiguous states; do not describe filtered as closed.
                if state in ("open", "open|filtered", "filtered"):
                    observation = {
                        "protocol": port.get("protocol"),
                        "port": port.get("portid"),
                        "state": state,
                        "state_reason": state_node.get("reason"),
                    }
                    if service_node is not None:
                        observation["service"] = {
                            key: service_node.get(key)
                            for key in ("name", "product", "version", "extrainfo", "method", "conf")
                            if service_node.get(key) is not None
                        }
                    evidence["port_observations"].append(observation)
    evidence["full_range_confirmed"] = any(
        entry.get("services") == "1-65535" and entry.get("numservices") == "65535"
        for entry in evidence["scaninfo"]
    )
    evidence["scan_completed"] = evidence["runstats_finished"] is not None and evidence["runstats_finished"].get("exit") == "success"
    return evidence


def main():
    # Complementary broad discovery probes; their raw envelopes are retained below.
    sweeps = [
        ("icmp_tcp", BASE + ["-sn", "-PE", "-PS22,80,443,445,3389,8080,52693", "192.168.0.0/16"]),
        ("tcp_udp", BASE + ["-sn", "-PE", "-PS22,80,443,445,3389,8080,52693", "-PU53,111,137,161,500,1900", "192.168.0.0/16"]),
    ]
    sweep_results = {}
    targets = set(PREVIOUSLY_OBSERVED)
    for name, argv in sweeps:
        result = invoke(argv)
        sweep_results[name] = result
        targets.update(responsive_hosts(result.get("result")))
    targets.discard(EXCLUDED)
    ordered_targets = sorted(targets)

    jobs = []
    for target in ordered_targets:
        for protocol, scan_type in (("tcp", "-sS"), ("udp", "-sU")):
            argv = [
                "nmap", "-n", scan_type, "-sV", "--reason", "-T4",
                "--exclude", EXCLUDED, "-p", "1-65535", "-oX", "-", target,
            ]
            jobs.append((target, protocol, argv))

    scans = {target: {} for target in ordered_targets}
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, max(1, len(jobs)))) as pool:
        future_map = {
            pool.submit(invoke, argv): (target, protocol, argv)
            for target, protocol, argv in jobs
        }
        for future in concurrent.futures.as_completed(future_map):
            target, protocol, argv = future_map[future]
            try:
                run = future.result()
            except Exception as exc:
                run = {"command": argv, "execution_error": repr(exc)}
            raw_envelope = run.get("result")
            evidence = completion_evidence(raw_envelope, protocol) if raw_envelope is not None else {
                "xml_found": False,
                "scaninfo": [],
                "runstats_finished": None,
                "port_observations": [],
                "full_range_confirmed": False,
                "scan_completed": False,
            }
            tool_error = run.get("execution_error")
            if tool_error:
                status = "failed"
            elif evidence["scan_completed"] and evidence["full_range_confirmed"]:
                status = "completed_full_range"
            elif raw_envelope is not None:
                status = "incomplete_or_unverified"
            else:
                status = "failed"
            scans[target][protocol] = {
                "attempted_ports": "1-65535",
                "service_identification_requested": True,
                "status": status,
                "coverage_evidence": evidence,
                "execution_error": tool_error,
                "raw_helper_envelope": raw_envelope,
            }

    print(json.dumps({
        "scope": "192.168.0.0/16",
        "excluded": EXCLUDED,
        "discovery_sweeps": sweep_results,
        "previously_observed_endpoints_included": sorted(PREVIOUSLY_OBSERVED - {EXCLUDED}),
        "deduplicated_targets": ordered_targets,
        "per_target_scans": scans,
        "interpretation_note": "Only completed full-range scan evidence supports coverage. Filtered, open|filtered, parser failures, missing XML, and execution errors are retained as uncertain or incomplete evidence, not negative findings. Previously assessed SSH/RPC findings are not classified as newly discovered here."
    }, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

