#!/usr/bin/env python3
import concurrent.futures
import json
import sys
import xml.etree.ElementTree as ET

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"status": "error", "stage": "import_framework_evidence", "error": str(exc)}))
    raise SystemExit(2)

EXCLUDED = "192.168.122.1"
KNOWN_ENDPOINTS = {
    "192.168.0.1": ["responsive endpoint in supplied census evidence"],
    "192.168.0.5": ["responsive endpoint in supplied census evidence; local interface address"],
    "192.168.3.1": ["responsive endpoint in supplied census evidence", "previously observed target"],
    "192.168.65.3": ["responsive endpoint in supplied census evidence", "previously observed target"],
    "192.168.65.6": ["responsive endpoint in supplied census evidence"],
}


def invoke(argv):
    try:
        value = run_tool(argv)
        return value, None
    except Exception as exc:
        return None, "%s: %s" % (type(exc).__name__, exc)


def xml_from_envelope(value):
    """Find raw Nmap XML in the helper envelope, including JSON-wrapped stdout."""
    seen = set()
    candidates = []

    def walk(obj):
        if isinstance(obj, dict):
            for key, item in obj.items():
                if key in ("stdout", "raw_stdout") and isinstance(item, str):
                    candidates.append(item)
                walk(item)
        elif isinstance(obj, list):
            for item in obj:
                walk(item)
        elif isinstance(obj, str):
            if obj in seen:
                return
            seen.add(obj)
            stripped = obj.lstrip()
            if stripped.startswith("{") or stripped.startswith("["):
                try:
                    walk(json.loads(obj))
                except Exception:
                    pass

    walk(value)
    for text in candidates:
        position = text.find("<?xml")
        if position < 0:
            position = text.find("<nmaprun")
        if position >= 0:
            ending = text.rfind("</nmaprun>")
            if ending >= position:
                return text[position:ending + len("</nmaprun>")]
    return None


def parse_nmap(value):
    raw_xml = xml_from_envelope(value)
    if raw_xml is None:
        return {"status": "unavailable", "error": "No Nmap XML found in tool output", "hosts": [], "raw_xml_available": False}
    try:
        root = ET.fromstring(raw_xml)
    except Exception as exc:
        return {"status": "parse_error", "error": str(exc), "hosts": [], "raw_xml_available": True}

    hosts = []
    for host in root.findall("host"):
        addresses = [a.get("addr") for a in host.findall("address") if a.get("addrtype") == "ipv4"]
        record = {
            "addresses": addresses,
            "status": host.find("status").get("state") if host.find("status") is not None else None,
            "ports": [],
        }
        for port in host.findall("./ports/port"):
            state_element = port.find("state")
            service_element = port.find("service")
            service = None
            if service_element is not None:
                service = {
                    "name": service_element.get("name"),
                    "product": service_element.get("product"),
                    "version": service_element.get("version"),
                    "extrainfo": service_element.get("extrainfo"),
                    "tunnel": service_element.get("tunnel"),
                    "method": service_element.get("method"),
                    "conf": service_element.get("conf"),
                }
            record["ports"].append({
                "protocol": port.get("protocol"),
                "port": int(port.get("portid")) if port.get("portid", "").isdigit() else port.get("portid"),
                "state": state_element.get("state") if state_element is not None else None,
                "reason": state_element.get("reason") if state_element is not None else None,
                "service": service,
            })
        hosts.append(record)

    finished = root.find("./runstats/finished")
    finished_record = None if finished is None else {
        "exit": finished.get("exit"),
        "summary": finished.get("summary"),
        "elapsed": finished.get("elapsed"),
        "timestr": finished.get("timestr"),
    }
    return {
        "status": "parsed",
        "hosts": hosts,
        "run_finished": finished_record,
        "scan_completed": bool(finished_record and finished_record.get("exit") == "success"),
        "raw_xml_available": True,
    }


def add_addresses(targets, parsed, source):
    for host in parsed.get("hosts", []):
        if host.get("status") != "up":
            continue
        for address in host.get("addresses", []):
            if address and address != EXCLUDED:
                targets.setdefault(address, []).append(source)


def scan_one(target, protocol):
    if protocol == "tcp":
        args = ["nmap", "-n", "-Pn", "-sS", "-sV", "--version-light", "-p", "1-65535"]
    else:
        args = ["nmap", "-n", "-Pn", "-sU", "-sV", "--version-light", "-p", "1-65535"]
    args += [
        "-T4", "--min-rate", "5000", "--max-retries", "1",
        "--initial-rtt-timeout", "100ms", "--max-rtt-timeout", "750ms",
        "--host-timeout", "105s", "-oX", "-", target,
    ]
    envelope, error = invoke(args)
    parsed = parse_nmap(envelope) if envelope is not None else {
        "status": "unavailable", "error": error, "hosts": [], "raw_xml_available": False
    }
    exit_codes = []

    def find_exit(obj):
        if isinstance(obj, dict):
            if "exit_code" in obj:
                exit_codes.append(obj.get("exit_code"))
            for item in obj.values():
                find_exit(item)
        elif isinstance(obj, list):
            for item in obj:
                find_exit(item)

    if envelope is not None:
        find_exit(envelope)
    process_ok = (0 in exit_codes) if exit_codes else False
    complete = process_ok and parsed.get("scan_completed") is True
    if error:
        status = "tool_error"
    elif complete:
        status = "completed"
    elif envelope is None:
        status = "failed_no_envelope"
    else:
        status = "incomplete_or_unverified"
    return {
        "target": target,
        "protocol": protocol,
        "attempted_port_range": "1-65535",
        "service_identification_requested": True,
        "nmap_arguments": args,
        "status": status,
        "tool_error": error,
        "observed_exit_codes": exit_codes,
        "machine_readable": parsed,
        "raw_tool_envelope": envelope,
    }


# Supplement the partial historical census evidence with a fresh, machine-readable sweep.
discovery_args = [
    "nmap", "-n", "-sn", "-PE", "-PS22,80,443,445,3389,8080,52693",
    "-T4", "--min-rate", "10000", "--max-retries", "1",
    "--initial-rtt-timeout", "200ms", "--max-rtt-timeout", "1000ms",
    "--exclude", EXCLUDED, "-oX", "-", "192.168.0.0/16",
]
discovery_envelope, discovery_error = invoke(discovery_args)
discovery_parsed = parse_nmap(discovery_envelope) if discovery_envelope is not None else {
    "status": "unavailable", "error": discovery_error, "hosts": [], "raw_xml_available": False
}

target_sources = {ip: list(sources) for ip, sources in KNOWN_ENDPOINTS.items()}
add_addresses(target_sources, discovery_parsed, "fresh supplementary Nmap host-discovery sweep")
target_sources.pop(EXCLUDED, None)
targets = sorted(target_sources)

scans = []
with concurrent.futures.ThreadPoolExecutor(max_workers=min(16, max(1, len(targets) * 2))) as pool:
    futures = [pool.submit(scan_one, target, protocol) for target in targets for protocol in ("tcp", "udp")]
    for future in concurrent.futures.as_completed(futures):
        try:
            scans.append(future.result())
        except Exception as exc:
            scans.append({"status": "worker_error", "error": "%s: %s" % (type(exc).__name__, exc)})
scans.sort(key=lambda item: (item.get("target", ""), item.get("protocol", "")))

coverage = {}
for target in targets:
    target_scans = [item for item in scans if item.get("target") == target]
    coverage[target] = {
        "sources": sorted(set(target_sources[target])),
        "excluded": False,
        "protocol_results": {
            protocol: next((item.get("status") for item in target_scans if item.get("protocol") == protocol), "not_attempted")
            for protocol in ("tcp", "udp")
        },
        "both_protocols_completed": all(
            any(item.get("protocol") == protocol and item.get("status") == "completed" for item in target_scans)
            for protocol in ("tcp", "udp")
        ),
    }

result = {
    "evidence_version": 1,
    "purpose": "Supplement partial census evidence, then scan every TCP and UDP port on each deduplicated in-scope target.",
    "excluded_target": EXCLUDED,
    "excluded_from_targets": EXCLUDED not in target_sources,
    "target_count": len(targets),
    "targets": targets,
    "target_sources": {ip: sorted(set(sources)) for ip, sources in sorted(target_sources.items())},
    "discovery": {
        "attempted_scope": "192.168.0.0/16",
        "excluded": EXCLUDED,
        "arguments": discovery_args,
        "tool_error": discovery_error,
        "parsed": discovery_parsed,
        "raw_tool_envelope": discovery_envelope,
    },
    "per_target_coverage": coverage,
    "scan_results": scans,
    "previously_assessed_evidence_not_new_findings": {
        "192.168.3.1": "SSH student:password login was previously rejected; this scan is new port/service coverage only.",
        "192.168.65.3": "RPC services were previously characterized; this scan is new port/service coverage only.",
    },
    "assessment_note": "Only parsed observations and tool-reported completion are evidence. Missing XML, failed commands, timeouts, and incomplete scans do not establish closed ports or absence of services.",
}
print(json.dumps(result, sort_keys=True, separators=(",", ":")))

