import concurrent.futures
import json
import sys
import xml.etree.ElementTree as ET

import framework_evidence

EXCLUDED = "192.168.122.1"
SEEDS = {
    # Responsive endpoints visible in the supplied host-discovery evidence,
    # plus the two previously observed targets required by this task.
    "192.168.0.1",
    "192.168.0.5",
    "192.168.3.1",
    "192.168.65.3",
    "192.168.65.6",
}
DISCOVERY_ARGV = [
    "nmap", "-n", "-sn", "-PE", "-PS22,80,443,445,3389,8080,52693",
    "-T4", "--min-rate", "10000", "--max-retries", "1",
    "--initial-rtt-timeout", "200ms", "--max-rtt-timeout", "1000ms",
    "--exclude", EXCLUDED, "-oX", "-", "192.168.0.0/16",
]


def find_xml(value):
    """Find raw Nmap XML nested anywhere in the evidence-helper envelope."""
    if isinstance(value, str):
        start = value.find("<?xml")
        if start >= 0:
            end = value.find("</nmaprun>", start)
            if end >= 0:
                return value[start:end + len("</nmaprun>")]
    elif isinstance(value, dict):
        for child in value.values():
            found = find_xml(child)
            if found:
                return found
    elif isinstance(value, (list, tuple)):
        for child in value:
            found = find_xml(child)
            if found:
                return found
    return None


def find_exit_code(value):
    if isinstance(value, dict):
        code = value.get("exit_code")
        if isinstance(code, int):
            return code
        for child in value.values():
            result = find_exit_code(child)
            if result is not None:
                return result
    elif isinstance(value, (list, tuple)):
        for child in value:
            result = find_exit_code(child)
            if result is not None:
                return result
    return None


def parse_discovery(envelope):
    xml_text = find_xml(envelope)
    if not xml_text:
        return [], {"xml_found": False, "parse_error": "No Nmap XML found in helper result"}
    try:
        root = ET.fromstring(xml_text)
        hosts = []
        for host in root.findall("host"):
            status = host.find("status")
            if status is None or status.get("state") != "up":
                continue
            for addr in host.findall("address"):
                if addr.get("addrtype") == "ipv4":
                    hosts.append(addr.get("addr"))
        stats = root.find("runstats/finished")
        return hosts, {
            "xml_found": True,
            "parse_error": None,
            "scan_finished": bool(stats is not None),
            "finish_exit": stats.get("exit") if stats is not None else None,
            "responsive_ipv4_count": len(set(hosts)),
        }
    except Exception as exc:
        return [], {"xml_found": True, "parse_error": str(exc)}


def summarize_scan(envelope):
    xml_text = find_xml(envelope)
    summary = {
        "helper_exit_code": find_exit_code(envelope),
        "xml_found": bool(xml_text),
        "xml_parse_error": None,
        "nmap_finished": False,
        "nmap_finish_exit": None,
        "requested_scaninfo": [],
        "port_state_counts": {},
        "ports_with_service_evidence": [],
    }
    if not xml_text:
        summary["completion"] = "incomplete_or_no_xml"
        return summary
    try:
        root = ET.fromstring(xml_text)
        for info in root.findall("scaninfo"):
            summary["requested_scaninfo"].append({
                "protocol": info.get("protocol"),
                "services": info.get("services"),
                "numservices": info.get("numservices"),
                "type": info.get("type"),
            })
        finished = root.find("runstats/finished")
        summary["nmap_finished"] = finished is not None
        summary["nmap_finish_exit"] = finished.get("exit") if finished is not None else None
        counts = {}
        service_evidence = []
        for port in root.findall(".//port"):
            state_el = port.find("state")
            if state_el is None:
                continue
            state = state_el.get("state", "unknown")
            counts[state] = counts.get(state, 0) + 1
            service = port.find("service")
            if service is not None:
                item = {
                    "protocol": port.get("protocol"),
                    "port": port.get("portid"),
                    "port_state": state,
                    "service_name": service.get("name"),
                    "product": service.get("product"),
                    "version": service.get("version"),
                    "extrainfo": service.get("extrainfo"),
                    "method": service.get("method"),
                    "conf": service.get("conf"),
                }
                service_evidence.append(item)
        summary["port_state_counts"] = counts
        summary["ports_with_service_evidence"] = service_evidence
        exit_code = summary["helper_exit_code"]
        summary["completion"] = (
            "completed" if summary["nmap_finished"]
            and summary["nmap_finish_exit"] == "success"
            and (exit_code is None or exit_code == 0)
            else "incomplete_or_failed"
        )
    except Exception as exc:
        summary["xml_parse_error"] = str(exc)
        summary["completion"] = "incomplete_or_unparsed"
    return summary


def scan_one(target, protocol):
    scan_type = "-sT" if protocol == "tcp" else "-sU"
    argv = [
        "nmap", "-n", scan_type, "-sV", "--version-light", "-p-",
        "-T5", "--min-rate", "5000", "--max-retries", "1",
        "--initial-rtt-timeout", "200ms", "--max-rtt-timeout", "1000ms",
        "--host-timeout", "95s", "--reason", "-oX", "-", target,
    ]
    record = {
        "target": target,
        "protocol": protocol,
        "requested_port_range": "1-65535",
        "argv": argv,
    }
    try:
        envelope = framework_evidence.run_tool(argv)
        record["summary"] = summarize_scan(envelope)
        record["raw_tool_envelope"] = envelope
    except Exception as exc:
        record["summary"] = {
            "completion": "failed_before_usable_result",
            "error": str(exc),
            "xml_found": False,
        }
    return record


def main():
    output = {
        "purpose": "Full TCP and UDP port/service assessment of discovered and previously observed in-scope endpoints",
        "excluded": EXCLUDED,
        "discovery_argv": DISCOVERY_ARGV,
    }
    try:
        discovery_envelope = framework_evidence.run_tool(DISCOVERY_ARGV)
        discovered, discovery_summary = parse_discovery(discovery_envelope)
        output["discovery"] = {
            "summary": discovery_summary,
            "raw_tool_envelope": discovery_envelope,
        }
    except Exception as exc:
        discovered = []
        output["discovery"] = {
            "summary": {"completion": "failed", "error": str(exc)},
            "raw_tool_envelope": None,
        }

    targets = sorted((SEEDS | set(discovered)) - {EXCLUDED})
    output["target_sources"] = {
        "runtime_discovery_ipv4": sorted(set(discovered)),
        "previously_observed_seed_endpoints": sorted(SEEDS),
    }
    output["targets"] = targets
    output["scans"] = []

    jobs = [(target, protocol) for target in targets for protocol in ("tcp", "udp")]
    # Separate per-target/protocol processes avoid the prior monolithic scan
    # failure mode while preserving an independent completion record for each.
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, len(jobs))) as pool:
        futures = {pool.submit(scan_one, target, protocol): (target, protocol)
                   for target, protocol in jobs}
        for future in concurrent.futures.as_completed(futures):
            target, protocol = futures[future]
            try:
                output["scans"].append(future.result())
            except Exception as exc:
                output["scans"].append({
                    "target": target,
                    "protocol": protocol,
                    "requested_port_range": "1-65535",
                    "summary": {"completion": "failed", "error": str(exc)},
                })
    output["scans"].sort(key=lambda item: (item["target"], item["protocol"]))
    output["coverage"] = {
        "requested_protocols": ["tcp", "udp"],
        "requested_port_range_per_protocol_per_target": "1-65535",
        "attempted_scan_count": len(output["scans"]),
        "expected_scan_count": len(targets) * 2,
        "incomplete_or_failed": [
            {"target": item["target"], "protocol": item["protocol"],
             "completion": item.get("summary", {}).get("completion")}
            for item in output["scans"]
            if item.get("summary", {}).get("completion") != "completed"
        ],
        "note": "Only completed XML runs establish completed scan coverage; absent or unparsed output is not a negative finding.",
    }
    json.dump(output, sys.stdout, sort_keys=True, default=str)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()

