import json
import os
import sys
from pathlib import Path

ARTIFACT = "llm_inputs/5b4df847f4fc39cbfce20afcc89979433ee45deb412f7a03f41eabade0ce7a93.json"
SCAN_NODE = "alternative_candidate_discovery__d1__all_port_service_scan"


def artifact_candidates():
    seen = set()
    supplied = os.environ.get("EVIDENCE_ARCHIVE_ROOT")
    roots = []
    if supplied:
        roots.append(Path(supplied))
    cwd = Path.cwd()
    roots.extend([cwd, *cwd.parents])
    for root in roots:
        candidate = (root / ARTIFACT).resolve()
        if candidate not in seen:
            seen.add(candidate)
            yield candidate


def decode_json_strings(value, depth=0):
    if depth > 12:
        return value
    if isinstance(value, dict):
        return {k: decode_json_strings(v, depth + 1) for k, v in value.items()}
    if isinstance(value, list):
        return [decode_json_strings(v, depth + 1) for v in value]
    if isinstance(value, str):
        text = value.strip()
        if text.startswith(("{", "[")):
            try:
                parsed = json.loads(text)
            except (json.JSONDecodeError, RecursionError):
                return value
            return decode_json_strings(parsed, depth + 1)
    return value


def walk(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from walk(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk(child)


def target_protocol_records(value):
    found = []
    seen = set()
    target_keys = {"target", "host", "ip", "address", "hostname", "target_ip"}
    for item in walk(value):
        protocol = item.get("protocol")
        has_target = any(k in item for k in target_keys)
        if protocol is not None and has_target:
            marker = json.dumps(item, sort_keys=True, ensure_ascii=False, default=str)
            if marker not in seen:
                seen.add(marker)
                found.append(item)
    return found


def main():
    artifact_path = next((p for p in artifact_candidates() if p.is_file()), None)
    if artifact_path is None:
        print(json.dumps({
            "retrieval_status": "incomplete",
            "parse_status": "not_attempted",
            "artifact": ARTIFACT,
            "searched_roots": [str(p) for p in artifact_candidates()],
            "limitation": "The specified retained original-input artifact was not found at the supplied relative path under the current directory, its ancestors, or EVIDENCE_ARCHIVE_ROOT. No scan findings can be inferred.",
            "scan_observations": []
        }, ensure_ascii=False))
        return 2

    try:
        with artifact_path.open("r", encoding="utf-8") as stream:
            source = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        print(json.dumps({
            "retrieval_status": "artifact_found",
            "parse_status": "failed",
            "artifact_path": str(artifact_path),
            "error": f"{type(exc).__name__}: {exc}",
            "scan_observations": []
        }, ensure_ascii=False))
        return 2

    source_root = source
    # The supplied source path is $.prior_observations. Accept the top-level
    # object directly, or a single wrapper containing the original input.
    if isinstance(source_root, dict) and "prior_observations" not in source_root:
        for value in source_root.values():
            if isinstance(value, dict) and "prior_observations" in value:
                source_root = value
                break
    prior = source_root.get("prior_observations") if isinstance(source_root, dict) else None
    if prior is None:
        print(json.dumps({
            "retrieval_status": "artifact_found",
            "parse_status": "source_path_missing",
            "artifact_path": str(artifact_path),
            "expected_source_path": "$.prior_observations",
            "limitation": "The artifact parsed as JSON, but the supplied source path was not present.",
            "scan_observations": []
        }, ensure_ascii=False))
        return 2

    matches = []
    for item in walk(prior):
        if item.get("node_id") != SCAN_NODE:
            continue
        execution = item.get("execution_result")
        if not isinstance(execution, dict):
            continue
        raw_stdout = execution.get("stdout")
        parsed_stdout = None
        stdout_parse_status = "missing"
        if isinstance(raw_stdout, str):
            try:
                parsed_stdout = decode_json_strings(json.loads(raw_stdout))
                stdout_parse_status = "parsed_json"
            except (json.JSONDecodeError, RecursionError):
                stdout_parse_status = "not_valid_json"
        elif raw_stdout is not None:
            parsed_stdout = decode_json_strings(raw_stdout)
            stdout_parse_status = "already_structured"

        matches.append({
            "observed_at": item.get("observed_at"),
            "goal": item.get("goal"),
            "execution_status": execution.get("status"),
            "exit_code": execution.get("exit_code"),
            "command": execution.get("command"),
            "stderr": execution.get("stderr"),
            "duration_seconds": execution.get("duration_seconds"),
            "structured_output": execution.get("structured_output"),
            "stdout_parse_status": stdout_parse_status,
            "retained_stdout": raw_stdout,
            "parsed_stdout": parsed_stdout,
            "target_protocol_records": target_protocol_records(parsed_stdout) if parsed_stdout is not None else []
        })

    print(json.dumps({
        "retrieval_status": "complete",
        "parse_status": "artifact_json_parsed",
        "artifact_path": str(artifact_path),
        "source_path": "$.prior_observations",
        "scan_node_id": SCAN_NODE,
        "matching_observation_count": len(matches),
        "scan_observations": matches,
        "coverage_note": "Interpret each retained execution status and nested per-target/per-protocol result independently. A timeout, missing output, or parser failure is not a completed negative scan. The script does not launch scans or manufacture absent results."
    }, ensure_ascii=False, default=str))
    return 0 if matches else 1


if __name__ == "__main__":
    sys.exit(main())

