#!/usr/bin/env python3
import hashlib
import json
import os
import sys

ARTIFACT = "llm_inputs/dd20011d614ee17d7541f75cb9e661440da42fe4520800640ab495a84d3b6204.json"
EXPECTED_SHA256 = "dd20011d614ee17d7541f75cb9e661440da42fe4520800640ab495a84d3b6204"
TARGET_MARKER = "alternative_candidate_discovery__d1__all_port_service_scan"


def emit(value):
    print(json.dumps(value, ensure_ascii=False, indent=2))


def locate_artifact():
    basename = os.path.basename(ARTIFACT)
    found = []
    errors = []
    directories_visited = 0
    skipped = {"proc", "sys", "dev"}

    for root, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=lambda e: errors.append(str(e))):
        dirs[:] = [d for d in dirs if d not in skipped]
        directories_visited += 1
        if basename in files:
            found.append(os.path.join(root, basename))

    valid = []
    hash_results = []
    for path in found:
        try:
            digest = hashlib.sha256()
            with open(path, "rb") as stream:
                for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                    digest.update(chunk)
            actual = digest.hexdigest()
            hash_results.append({"path": path, "sha256": actual, "matches_expected": actual == EXPECTED_SHA256})
            if actual == EXPECTED_SHA256:
                valid.append(path)
        except OSError as exc:
            hash_results.append({"path": path, "error": str(exc)})
    return valid, {"artifact_relative_path": ARTIFACT, "basename_matches": found,
                   "sha256_checks": hash_results, "directories_visited": directories_visited,
                   "search_errors": errors}


def matching_records(value, path="$", output=None):
    if output is None:
        output = []
    if isinstance(value, dict):
        node_id = value.get("node_id")
        if isinstance(node_id, str) and TARGET_MARKER in node_id:
            output.append({"source_path": path, "observation": value})
        for key, child in value.items():
            matching_records(child, path + "[" + json.dumps(key, ensure_ascii=False) + "]", output)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            matching_records(child, path + "[" + str(index) + "]", output)
    return output


def main():
    paths, search = locate_artifact()
    if not paths:
        emit({"retrieval_status": "not_found_or_hash_mismatch",
              "parse_status": "not_attempted",
              "limitation": "No accessible file with the archived input basename passed the supplied SHA-256 check.",
              "search": search})
        return 0

    path = paths[0]
    try:
        with open(path, "r", encoding="utf-8") as stream:
            original = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        emit({"retrieval_status": "retrieved_hash_verified", "archive_path": path,
              "parse_status": "failed", "parse_error": str(exc), "search": search})
        return 0

    if not isinstance(original, dict) or "prior_observations" not in original:
        emit({"retrieval_status": "retrieved_hash_verified", "archive_path": path,
              "parse_status": "json_parsed_source_missing",
              "limitation": "The archived JSON has no top-level prior_observations field.",
              "top_level_type": type(original).__name__, "search": search})
        return 0

    prior = original["prior_observations"]
    records = matching_records(prior)
    emit({"retrieval_status": "retrieved_hash_verified", "archive_path": path,
          "archive_sha256": EXPECTED_SHA256,
          "parse_status": "parsed", "prior_observations_type": type(prior).__name__,
          "scan_observation_count": len(records),
          "scan_observations": records,
          "scan_observation_status": "found" if records else "not_found_in_parsed_prior_observations",
          "coverage_note": "Only retained matching observations are reported. Missing records or incomplete/truncated outputs are not interpreted as completed negative scan results.",
          "search": search})


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        emit({"retrieval_status": "error", "error_type": type(exc).__name__, "error": str(exc)})
        sys.exit(1)

