import concurrent.futures
import json
import re
import sys

import framework_evidence

HOSTS = [
    "192.168.0.1",
    "192.168.0.5",
    "192.168.3.1",
    "192.168.65.3",
    "192.168.65.6",
]
EXCLUDED = "192.168.122.1"
PORT_SPEC = "T:1-65535,U:1-65535"


def run_scan(host):
    if host == EXCLUDED:
        return host, None, "excluded by task"
    argv = [
        "nmap", "-n", "-Pn", "-sS", "-sU", "-T4",
        "--min-rate", "4000", "--max-retries", "1",
        "-p", PORT_SPEC, host,
    ]
    try:
        return host, framework_evidence.run_tool(argv), None
    except Exception as exc:
        return host, None, "run_tool raised " + type(exc).__name__ + ": " + str(exc)


def tool_runs(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list):
            return runs
        if "exit_code" in envelope or "stdout" in envelope:
            return [envelope]
    return []


def scan_evidence(envelope):
    runs = tool_runs(envelope)
    output = "\n".join(
        str(run.get("stdout", "")) for run in runs if isinstance(run, dict)
    )
    successful = bool(runs) and all(
        isinstance(run, dict)
        and run.get("status") == "completed"
        and run.get("exit_code") == 0
        and "Nmap done:" in str(run.get("stdout", ""))
        for run in runs
    )
    open_ports = []
    ambiguous_ports = []
    for line in output.splitlines():
        match = re.match(r"^\s*(\d+)/(tcp|udp)\s+(\S+)\s+(\S+)", line)
        if not match:
            continue
        port, protocol, state, service = match.groups()
        finding = {"port": int(port), "protocol": protocol, "state": state, "service_label": service}
        if state == "open":
            open_ports.append(finding)
        elif state == "open|filtered":
            ambiguous_ports.append(finding)
    return runs, successful, open_ports, ambiguous_ports


def main():
    results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(HOSTS)) as pool:
        futures = [pool.submit(run_scan, host) for host in HOSTS]
        for future in concurrent.futures.as_completed(futures):
            host, envelope, error = future.result()
            if error:
                results[host] = {
                    "tcp_coverage": {"requested": "1-65535", "status": "incomplete_or_unknown", "reason": error},
                    "udp_coverage": {"requested": "1-65535", "status": "incomplete_or_unknown", "reason": error},
                    "open_ports": [],
                    "ambiguous_open_or_filtered_ports": [],
                    "raw_evidence_envelope": envelope,
                }
                continue
            runs, complete, open_ports, ambiguous = scan_evidence(envelope)
            status = "complete" if complete else "incomplete_or_unknown"
            reason = (
                "Nmap reported completion and successful exit for the requested combined scan."
                if complete else
                "No successful Nmap completion record was established; do not infer coverage from missing output."
            )
            results[host] = {
                "tcp_coverage": {"requested": "1-65535", "status": status, "reason": reason},
                "udp_coverage": {"requested": "1-65535", "status": status, "reason": reason},
                "open_ports": open_ports,
                "ambiguous_open_or_filtered_ports": ambiguous,
                "tool_run_count": len(runs),
                "raw_evidence_envelope": envelope,
            }

    report = {
        "purpose": "Full TCP and UDP port coverage on discovered responsive hosts",
        "scope": {"hosts": HOSTS, "excluded_host": EXCLUDED, "tcp_ports": "1-65535", "udp_ports": "1-65535"},
        "results": {host: results[host] for host in HOSTS},
        "coverage_note": "TCP and UDP status reflects completion of the combined Nmap invocation; raw output and structured observations are retained for review. A port row marked open|filtered is not asserted to be open.",
    }
    print(json.dumps(report, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

