import concurrent.futures
import json
import re
import sys

TARGET = "192.168.3.1"
BATCH_SIZE = 4096
MAX_WORKERS = 16
HOST_TIMEOUT = "40s"

PRIOR_TCP_BATCHES = [
    [0, 4095], [4096, 8191], [8192, 12287], [12288, 16383],
    [16384, 20479], [20480, 24575], [24576, 28671],
]


def ranges(start, end, size):
    result = []
    current = start
    while current <= end:
        last = min(current + size - 1, end)
        result.append([current, last])
        current = last + 1
    return result


def make_argv(protocol, port_range):
    low, high = port_range
    nmap_protocol = "T" if protocol == "tcp" else "U"
    scan_type = "-sS" if protocol == "tcp" else "-sU"
    return [
        "nmap", "-n", "-Pn", "-T4", "--min-rate", "500",
        "--max-retries", "1", "--host-timeout", HOST_TIMEOUT,
        scan_type, "-sV", "-p", f"{nmap_protocol}:{low}-{high}", TARGET,
    ]


def inspect_envelope(envelope):
    """Return a conservative completion assessment; preserve envelope separately."""
    if not isinstance(envelope, dict):
        return {"status": "unknown", "actual_coverage": "unknown: tool returned a non-object envelope"}
    runs = envelope.get("tool_runs")
    if not isinstance(runs, list) or not runs:
        return {"status": envelope.get("status", "unknown"),
                "actual_coverage": "unknown: no tool_runs evidence in envelope"}

    run_summaries = []
    all_complete = True
    for run in runs:
        if not isinstance(run, dict):
            all_complete = False
            run_summaries.append({"status": "unknown", "exit_code": None,
                                  "scan_completed": False})
            continue
        structured = run.get("structured_output")
        parsed_complete = (isinstance(structured, dict)
                           and structured.get("scan_completed") is True)
        stdout = run.get("stdout") if isinstance(run.get("stdout"), str) else ""
        nmap_done = bool(re.search(r"Nmap done: .* scanned in ", stdout))
        exit_code = run.get("exit_code")
        completed = (run.get("status") == "completed" and exit_code == 0
                     and (parsed_complete or nmap_done))
        all_complete = all_complete and completed
        run_summaries.append({
            "status": run.get("status", "unknown"),
            "exit_code": exit_code,
            "structured_scan_completed": parsed_complete,
            "nmap_done_line_observed": nmap_done,
            "scan_completed": completed,
        })

    status = "completed" if all_complete else "incomplete_or_failed"
    coverage = ("requested batch completed according to tool status and Nmap completion evidence"
                if all_complete else
                "requested range was attempted, but full batch coverage is not established")
    return {"status": status, "actual_coverage": coverage,
            "tool_run_assessments": run_summaries}


def run_batch(item):
    protocol, port_range = item
    argv = make_argv(protocol, port_range)
    record = {
        "target": TARGET,
        "protocol": protocol,
        "requested_port_range": port_range,
        "argv": argv,
    }
    try:
        import framework_evidence
        envelope = framework_evidence.run_tool(argv)
        record["execution_result"] = envelope
        record["assessment"] = inspect_envelope(envelope)
    except Exception as exc:
        record["execution_result"] = None
        record["assessment"] = {
            "status": "failed",
            "actual_coverage": "none established",
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
    return record


def merge_ranges(intervals):
    if not intervals:
        return []
    ordered = sorted((int(a), int(b)) for a, b in intervals)
    merged = [list(ordered[0])]
    for low, high in ordered[1:]:
        if low <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], high)
        else:
            merged.append([low, high])
    return merged


def gaps(covered, start, end):
    result = []
    cursor = start
    for low, high in merge_ranges(covered):
        if high < start or low > end:
            continue
        low = max(low, start)
        high = min(high, end)
        if low > cursor:
            result.append([cursor, low - 1])
        cursor = max(cursor, high + 1)
    if cursor <= end:
        result.append([cursor, end])
    return result


def main():
    tcp_batches = ranges(28672, 65535, BATCH_SIZE)
    udp_batches = ranges(0, 65535, BATCH_SIZE)
    work = [("tcp", r) for r in tcp_batches] + [("udp", r) for r in udp_batches]
    records = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_WORKERS) as pool:
        futures = {pool.submit(run_batch, item): item for item in work}
        for future in concurrent.futures.as_completed(futures):
            try:
                records.append(future.result())
            except Exception as exc:
                protocol, port_range = futures[future]
                records.append({
                    "target": TARGET,
                    "protocol": protocol,
                    "requested_port_range": port_range,
                    "assessment": {"status": "failed", "actual_coverage": "none established",
                                   "error_type": type(exc).__name__, "error": str(exc)},
                })

    records.sort(key=lambda r: (r["protocol"], r["requested_port_range"][0]))
    complete = {"tcp": [], "udp": []}
    for record in records:
        if record.get("assessment", {}).get("status") == "completed":
            complete[record["protocol"]].append(record["requested_port_range"])

    prior_complete = list(PRIOR_TCP_BATCHES)
    combined_tcp = prior_complete + complete["tcp"]
    output = {
        "target": TARGET,
        "batch_size": BATCH_SIZE,
        "parallel_workers": MAX_WORKERS,
        "per_batch_host_timeout": HOST_TIMEOUT,
        "prior_evidence": {
            "source": "dependency observation from the prior inventory attempt",
            "recorded_tcp_batches": PRIOR_TCP_BATCHES,
            "recorded_tcp_coverage": [0, 28671],
            "reported_observation": "Each of the seven completed batches reported 4096 filtered TCP ports (no-response).",
            "raw_prior_results": "Retained in the dependency observation; not rerun here.",
        },
        "batches": records,
        "coverage_summary": {
            "tcp_requested_full_range": [0, 65535],
            "tcp_completed_ranges_including_prior": merge_ranges(combined_tcp),
            "tcp_missing_or_incomplete_ranges": gaps(combined_tcp, 0, 65535),
            "udp_requested_full_range": [0, 65535],
            "udp_completed_ranges": merge_ranges(complete["udp"]),
            "udp_missing_or_incomplete_ranges": gaps(complete["udp"], 0, 65535),
        },
        "interpretation": "Only batches with recorded successful tool status and Nmap completion evidence count as completed coverage. Incomplete batches are not negative port findings.",
    }
