import concurrent.futures
import json
import re
import sys

import framework_evidence

TARGET = "192.168.3.1"
BATCH_SIZE = 1024
WORKERS = 8


def ranges(start, end, size):
    result = []
    current = start
    while current <= end:
        last = min(current + size - 1, end)
        result.append((current, last))
        current = last + 1
    return result


def make_batches():
    batches = []
    # Prior evidence records TCP 0-28671. Only scan the remaining TCP ports.
    for first, last in ranges(28672, 65535, 4096):
        batches.append(("tcp", first, last))
    # Recheck the full UDP range in smaller batches; this subdivides the range
    # that previously included a host-timeout report.
    for first, last in ranges(0, 65535, BATCH_SIZE):
        batches.append(("udp", first, last))
    return batches


def execute_batch(batch):
    protocol, first, last = batch
    if protocol == "tcp":
        argv = [
            "nmap", "-n", "-Pn", "-T4", "--min-rate", "500",
            "--max-retries", "1", "-sS", "-sV", "-p",
            "T:{}-{}".format(first, last), TARGET,
        ]
    else:
        argv = [
            "nmap", "-n", "-Pn", "-T4", "--min-rate", "1000",
            "--max-retries", "1", "-sU", "-sV", "--version-light",
            "-p", "U:{}-{}".format(first, last), TARGET,
        ]

    record = {
        "target": TARGET,
        "protocol": protocol,
        "requested_port_range": [first, last],
        "argv": argv,
    }
    try:
        envelope = framework_evidence.run_tool(argv)
        record["raw_execution_result"] = envelope
        runs = envelope.get("tool_runs", []) if isinstance(envelope, dict) else []
        stdout_parts = []
        successful_tool_run = False
        for run in runs:
            if not isinstance(run, dict):
                continue
            stdout_parts.append(str(run.get("stdout", "")))
            if run.get("status") == "completed" and run.get("exit_code") == 0:
                successful_tool_run = True
        stdout = "\n".join(stdout_parts)
        host_timeout = bool(re.search(
            r"Skipping host .* due to host timeout|host timed out",
            stdout, re.IGNORECASE,
        ))
        nmap_finished = bool(re.search(r"Nmap done:", stdout))
        complete = successful_tool_run and nmap_finished and not host_timeout
        record["execution_status"] = "completed" if successful_tool_run else "failed_or_incomplete"
        record["nmap_completion_observed"] = nmap_finished
        record["host_timeout_observed"] = host_timeout
        record["actual_coverage"] = [first, last] if complete else None
        record["coverage_status"] = "confirmed_full_batch" if complete else "incomplete_or_unconfirmed"
        if not runs:
            record["coverage_note"] = "No tool_runs entry was available to verify this batch."
        elif host_timeout:
            record["coverage_note"] = "Nmap reported a host timeout; this batch is not counted as covered."
        elif not complete:
            record["coverage_note"] = "Tool completion and Nmap completion evidence did not both establish full batch coverage."
    except Exception as exc:
        record.update({
            "execution_status": "error",
            "actual_coverage": None,
            "coverage_status": "incomplete_or_unconfirmed",
            "error": "{}: {}".format(type(exc).__name__, exc),
        })
    return record


def missing_ranges(covered, start, end):
    intervals = sorted(
        (max(start, a), min(end, b))
        for a, b in covered
        if a <= end and b >= start
    )
    merged = []
    for first, last in intervals:
        if not merged or first > merged[-1][1] + 1:
            merged.append([first, last])
        else:
            merged[-1][1] = max(merged[-1][1], last)
    missing = []
    cursor = start
    for first, last in merged:
        if cursor < first:
            missing.append([cursor, first - 1])
        cursor = max(cursor, last + 1)
    if cursor <= end:
        missing.append([cursor, end])
    return missing


def main():
    batches = make_batches()
    records = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = {pool.submit(execute_batch, batch): batch for batch in batches}
        for future in concurrent.futures.as_completed(futures):
            records.append(future.result())

    records.sort(key=lambda r: (r["protocol"], r["requested_port_range"][0]))
    tcp_covered = [[0, 28671]]  # Coverage explicitly recorded in the prior attempt.
    udp_covered = []
    for record in records:
        if record.get("coverage_status") != "confirmed_full_batch":
            continue
        if record["protocol"] == "tcp":
            tcp_covered.append(record["actual_coverage"])
        else:
            udp_covered.append(record["actual_coverage"])

    output = {
        "target": TARGET,
        "parallel_workers": WORKERS,
        "prior_evidence": {
            "protocol": "tcp",
            "recorded_coverage": [0, 28671],
            "basis": "Dependency evidence for this node records completed TCP batches covering ports 0-28671.",
        },
        "batches": records,
        "coverage_summary": {
            "tcp_requested_full_range": [0, 65535],
            "tcp_completed_ranges_including_prior": tcp_covered,
            "tcp_missing_or_incomplete_ranges": missing_ranges(tcp_covered, 0, 65535),
            "udp_requested_full_range": [0, 65535],
            "udp_completed_ranges": udp_covered,
            "udp_missing_or_incomplete_ranges": missing_ranges(udp_covered, 0, 65535),
        },
        "interpretation": "Only batches with successful tool status, Nmap completion evidence, and no host-timeout indication count as full coverage. Raw tool envelopes are retained; incomplete batches are not negative port findings.",
    }
    json.dump(output, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()

