import concurrent.futures
import json
import sys
import traceback

import framework_evidence

TARGET = "192.168.3.1"
TCP_PRIOR = [[0, 4095], [4096, 8191], [8192, 12287], [12288, 16383],
             [16384, 20479], [20480, 24575], [24576, 28671]]


def ranges(start, end, size):
    first = start
    while first <= end:
        last = min(first + size - 1, end)
        yield [first, last]
        first = last + 1


batches = []
for protocol, spans, scan_type in (
    ("tcp", ranges(28672, 65535, 4096), "-sS"),
    ("udp", ranges(0, 65535, 1024), "-sU"),
):
    for span in spans:
        port_range = f"{span[0]}-{span[1]}"
        argv = ["nmap", "-n", "-Pn", "-T4", "--min-rate", "500",
                "--max-retries", "1", scan_type, "-sV", "-p",
                f"{protocol[0].upper()}:{port_range}", TARGET]
        batches.append({"protocol": protocol, "requested_port_range": span,
                        "argv": argv})

print(json.dumps({
    "record_type": "inventory_plan",
    "target": TARGET,
    "inherited_tcp_coverage": {
        "ranges": TCP_PRIOR,
        "source": "dependency evidence from the prior attempt",
        "recorded_result": "each batch completed; 4096 ports reported filtered (no response)"
    },
    "new_batches_planned": len(batches),
    "batch_sizes": {"tcp": 4096, "udp": 1024},
    "coverage_rule": "Only a successful tool run with structured scan_completed=true confirms a batch; otherwise coverage is unverified or incomplete."
}, sort_keys=True), flush=True)


def execute(batch):
    record = {
        "target": TARGET,
        "protocol": batch["protocol"],
        "requested_port_range": batch["requested_port_range"],
        "argv": batch["argv"],
    }
    try:
        envelope = framework_evidence.run_tool(batch["argv"])
        record["execution_result"] = envelope
        runs = envelope.get("tool_runs", []) if isinstance(envelope, dict) else []
        if not runs:
            record["actual_coverage"] = "unverified: no structured tool run was returned"
        else:
            successful = any(
                run.get("exit_code") == 0 and run.get("status") == "completed"
                for run in runs if isinstance(run, dict)
            )
            completed_scan = any(
                isinstance(run, dict)
                and isinstance(run.get("structured_output"), dict)
                and run["structured_output"].get("scan_completed") is True
                for run in runs
            )
            if successful and completed_scan:
                record["actual_coverage"] = "confirmed: requested batch completed according to structured Nmap observation"
            elif successful:
                record["actual_coverage"] = "unverified: tool completed but structured scan completion was not confirmed"
            else:
                record["actual_coverage"] = "incomplete_or_failed: requested range is not counted as covered"
    except Exception as exc:
        record["execution_result"] = {
            "status": "exception",
            "error_type": type(exc).__name__,
            "error": str(exc),
            "traceback": traceback.format_exc(),
        }
        record["actual_coverage"] = "incomplete_or_failed: tool invocation raised an exception"
    return record


# Keep the number of concurrent Nmap processes bounded while scanning independent batches in parallel.
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as pool:
    futures = [pool.submit(execute, batch) for batch in batches]
    for future in concurrent.futures.as_completed(futures):
        try:
            record = future.result()
        except Exception as exc:
            record = {"record_type": "worker_error", "error_type": type(exc).__name__, "error": str(exc)}
        print(json.dumps(record, sort_keys=True, ensure_ascii=False), flush=True)

