import concurrent.futures
import json
import sys

from framework_evidence import run_tool

TARGET = "192.168.3.1"
BATCH_SIZE = 4096
WORKERS = 25

# These ranges are documented as completed in the supplied dependency evidence.
PRIOR_TCP_BATCHES = [
    [0, 4095], [4096, 8191], [8192, 12287], [12288, 16383],
    [16384, 20479], [20480, 24575], [24576, 28671],
]


def batches(start, end, size):
    current = start
    while current <= end:
        last = min(current + size - 1, end)
        yield current, last
        current = last + 1


def make_jobs():
    jobs = []
    for protocol, start, end, scan_flag, port_prefix in (
        ("tcp", 28672, 65535, "-sS", "T"),
        ("udp", 0, 65535, "-sU", "U"),
    ):
        for first, last in batches(start, end, BATCH_SIZE):
            argv = [
                "nmap", "-n", "-Pn", "-T4", "--min-rate", "500",
                "--max-retries", "1", "--host-timeout", "90s",
                scan_flag, "-sV", "-p", f"{port_prefix}:{first}-{last}", TARGET,
            ]
            jobs.append({
                "target": TARGET,
                "protocol": protocol,
                "requested_port_range": [first, last],
                "argv": argv,
            })
    return jobs


def assess_coverage(envelope):
    """Assess only explicit tool/parser evidence; retain the raw envelope separately."""
    if not isinstance(envelope, dict):
        return {"status": "unknown", "reason": "Tool returned no structured envelope."}
    runs = envelope.get("tool_runs")
    if not isinstance(runs, list) or not runs:
        return {
            "status": "unknown",
            "reason": "No tool_runs record; requested range coverage is unconfirmed.",
        }
    assessments = []
    for run in runs:
        if not isinstance(run, dict):
            assessments.append({"status": "unknown", "reason": "Malformed tool run record."})
            continue
        parsed = run.get("structured_output")
        parsed_complete = isinstance(parsed, dict) and parsed.get("scan_completed") is True
        completed = run.get("status") == "completed" and run.get("exit_code") == 0
        if completed and parsed_complete:
            assessments.append({
                "status": "confirmed_complete",
                "reason": "Tool run exited successfully and the parser marks the scan complete.",
            })
        elif not completed:
            assessments.append({
                "status": "incomplete_or_failed",
                "reason": "Tool run did not report completed status with exit code 0.",
                "tool_status": run.get("status"),
                "exit_code": run.get("exit_code"),
            })
        else:
            assessments.append({
                "status": "unconfirmed",
                "reason": "Tool exited successfully, but structured scan completion is not confirmed.",
                "parser_status": parsed.get("status") if isinstance(parsed, dict) else None,
            })
    if all(item["status"] == "confirmed_complete" for item in assessments):
        status = "confirmed_complete"
    elif any(item["status"] == "incomplete_or_failed" for item in assessments):
        status = "incomplete_or_failed"
    else:
        status = "unconfirmed"
    return {"status": status, "tool_run_assessments": assessments}


def run_batch(job):
    try:
        envelope = run_tool(job["argv"])
        return {
            **job,
            "execution_status": "returned",
            "coverage": assess_coverage(envelope),
            "raw_result": envelope,
        }
    except Exception as exc:
        return {
            **job,
            "execution_status": "error",
            "coverage": {
                "status": "incomplete_or_failed",
                "reason": "The evidence helper raised an exception; requested range is not confirmed covered.",
            },
            "error": f"{type(exc).__name__}: {exc}",
        }


def main():
    jobs = make_jobs()
    results = []
    print(json.dumps({
        "record_type": "inventory_start",
        "target": TARGET,
        "prior_tcp_batches_recorded": PRIOR_TCP_BATCHES,
        "prior_tcp_coverage_claimed_by_dependency": [0, 28671],
        "new_batch_count": len(jobs),
        "batch_size_max": BATCH_SIZE,
        "parallel_workers": WORKERS,
        "note": "Prior coverage is reported from dependency evidence; no prior batch is rescanned here.",
    }), flush=True)

    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        future_jobs = {pool.submit(run_batch, job): job for job in jobs}
        for future in concurrent.futures.as_completed(future_jobs):
            try:
                result = future.result()
            except Exception as exc:
                job = future_jobs[future]
                result = {
                    **job,
                    "execution_status": "worker_error",
                    "coverage": {"status": "incomplete_or_failed", "reason": str(exc)},
                }
            results.append(result)
            print(json.dumps({"record_type": "batch_result", **result}, sort_keys=True), flush=True)

    incomplete = [
        {
            "protocol": item["protocol"],
            "requested_port_range": item["requested_port_range"],
            "coverage_status": item.get("coverage", {}).get("status", "unknown"),
        }
        for item in results
        if item.get("coverage", {}).get("status") != "confirmed_complete"
    ]
    print(json.dumps({
        "record_type": "inventory_summary",
        "target": TARGET,
        "prior_tcp_batches_recorded": PRIOR_TCP_BATCHES,
        "new_batches_total": len(jobs),
        "new_batches_confirmed_complete": sum(
            item.get("coverage", {}).get("status") == "confirmed_complete"
            for item in results
        ),
        "incomplete_or_unconfirmed_batches": incomplete,
        "tcp_full_coverage_confirmed": not any(
            item["protocol"] == "tcp" for item in incomplete
        ),
        "udp_full_coverage_confirmed": not any(
            item["protocol"] == "udp" for item in incomplete
        ),
        "interpretation": "Only explicit confirmed batch coverage counts; incomplete or unconfirmed batches are not negative port findings.",
    }, sort_keys=True), flush=True)


if __name__ == "__main__":
    main()

