import json
import socket
import struct
import time

TARGETS = [
    {"host": "192.168.0.1", "tcp_port": 41227, "udp_port": 54755},
    {"host": "192.168.65.6", "tcp_port": 41227, "udp_port": 54755},
]
PROGRAM = 100024
VERSIONS = (1, 2, 3, 4)
TIMEOUT_SECONDS = 2.0
MAX_TCP_RECORD = 1024 * 1024


def make_call(xid, version):
    # ONC RPC CALL, RPC version 2, NULL procedure, AUTH_NULL credentials/verifier.
    return struct.pack(
        "!10I", xid, 0, 2, PROGRAM, version, 0, 0, 0, 0, 0
    )


def read_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise EOFError("peer closed before the complete RPC record arrived")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)


def read_tcp_record(sock):
    record = bytearray()
    while True:
        marker = struct.unpack("!I", read_exact(sock, 4))[0]
        last_fragment = bool(marker & 0x80000000)
        fragment_length = marker & 0x7fffffff
        if len(record) + fragment_length > MAX_TCP_RECORD:
            raise ValueError("RPC TCP record exceeds the 1 MiB probe limit")
        if fragment_length:
            record.extend(read_exact(sock, fragment_length))
        if last_fragment:
            return bytes(record)


def parse_reply(data, expected_xid):
    result = {"parse_status": "ok", "rpc_reply_status": None}
    if len(data) < 12:
        raise ValueError("RPC reply is shorter than its fixed header")
    xid, message_type, reply_stat = struct.unpack_from("!3I", data, 0)
    result.update({"xid": xid, "message_type": message_type})
    if xid != expected_xid:
        result["parse_status"] = "xid_mismatch"
        result["rpc_reply_status"] = "response_xid_does_not_match_request"
        return result
    if message_type != 1:
        result["parse_status"] = "unexpected_message_type"
        result["rpc_reply_status"] = "not_an_rpc_reply"
        return result

    result["reply_stat"] = reply_stat
    offset = 12
    if reply_stat == 0:  # MSG_ACCEPTED
        if len(data) < offset + 8:
            raise ValueError("accepted reply lacks verifier header and accept status")
        verifier_flavor, verifier_length = struct.unpack_from("!2I", data, offset)
        offset += 8
        padded_length = (verifier_length + 3) & ~3
        if verifier_length > len(data) or len(data) < offset + padded_length + 4:
            raise ValueError("accepted reply has a truncated verifier or status")
        result["verifier_flavor"] = verifier_flavor
        result["verifier_length"] = verifier_length
        accept_stat = struct.unpack_from("!I", data, offset + padded_length)[0]
        result["accept_stat"] = accept_stat
        names = {
            0: "success",
            1: "program_unavailable",
            2: "program_version_mismatch",
            3: "procedure_unavailable",
            4: "garbage_arguments",
            5: "system_error",
        }
        result["rpc_reply_status"] = names.get(accept_stat, "unknown_accept_status")
        if accept_stat == 2 and len(data) >= offset + padded_length + 12:
            low, high = struct.unpack_from("!2I", data, offset + padded_length + 4)
            result["version_range"] = {"low": low, "high": high}
    elif reply_stat == 1:  # MSG_DENIED
        if len(data) < offset + 4:
            raise ValueError("denied reply lacks reject status")
        reject_stat = struct.unpack_from("!I", data, offset)[0]
        result["reject_stat"] = reject_stat
        if reject_stat == 0:  # RPC_MISMATCH
            result["rpc_reply_status"] = "rpc_version_mismatch"
            if len(data) >= offset + 12:
                low, high = struct.unpack_from("!2I", data, offset + 4)
                result["rpc_version_range"] = {"low": low, "high": high}
        elif reject_stat == 1:
            result["rpc_reply_status"] = "authentication_error"
            if len(data) >= offset + 8:
                result["auth_status"] = struct.unpack_from("!I", data, offset + 4)[0]
        else:
            result["rpc_reply_status"] = "unknown_reject_status"
    else:
        result["rpc_reply_status"] = "unknown_reply_status"
    return result


def probe_tcp(host, port, version, xid):
    outcome = {
        "host": host, "transport": "tcp", "port": port,
        "program": PROGRAM, "version": version, "procedure": 0,
        "xid": xid,
    }
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(TIMEOUT_SECONDS)
    started = time.monotonic()
    try:
        sock.connect((host, port))
        body = make_call(xid, version)
        sock.sendall(struct.pack("!I", 0x80000000 | len(body)) + body)
        reply = read_tcp_record(sock)
        outcome["outcome"] = "response_received"
        outcome["raw_reply_hex"] = reply.hex()
        outcome["response_bytes"] = len(reply)
        try:
            outcome["parsed_reply"] = parse_reply(reply, xid)
        except (ValueError, struct.error) as exc:
            outcome["parser_error"] = str(exc)
            outcome["parsed_reply"] = {"parse_status": "error"}
    except socket.timeout as exc:
        outcome["outcome"] = "timeout"
        outcome["error"] = str(exc) or "socket operation timed out"
    except OSError as exc:
        outcome["outcome"] = "socket_error"
        outcome["error"] = "%s: %s" % (type(exc).__name__, exc)
    except (EOFError, ValueError, struct.error) as exc:
        outcome["outcome"] = "response_or_protocol_error"
        outcome["error"] = "%s: %s" % (type(exc).__name__, exc)
    finally:
        outcome["duration_seconds"] = round(time.monotonic() - started, 4)
        sock.close()
    return outcome


def probe_udp(host, port, version, xid):
    outcome = {
        "host": host, "transport": "udp", "port": port,
        "program": PROGRAM, "version": version, "procedure": 0,
        "xid": xid,
    }
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(TIMEOUT_SECONDS)
    started = time.monotonic()
    try:
        sock.sendto(make_call(xid, version), (host, port))
        reply, source = sock.recvfrom(65535)
        outcome["outcome"] = "response_received"
        outcome["response_source"] = {"address": source[0], "port": source[1]}
        outcome["raw_reply_hex"] = reply.hex()
        outcome["response_bytes"] = len(reply)
        try:
            outcome["parsed_reply"] = parse_reply(reply, xid)
        except (ValueError, struct.error) as exc:
            outcome["parser_error"] = str(exc)
            outcome["parsed_reply"] = {"parse_status": "error"}
    except socket.timeout as exc:
        outcome["outcome"] = "timeout"
        outcome["error"] = str(exc) or "socket operation timed out"
    except OSError as exc:
        outcome["outcome"] = "socket_error"
        outcome["error"] = "%s: %s" % (type(exc).__name__, exc)
    finally:
        outcome["duration_seconds"] = round(time.monotonic() - started, 4)
        sock.close()
    return outcome


def main():
    observations = []
    xid = 0x52435000
    for target in TARGETS:
        for version in VERSIONS:
            xid += 1
            observations.append(probe_tcp(
                target["host"], target["tcp_port"], version, xid
            ))
            xid += 1
            observations.append(probe_udp(
                target["host"], target["udp_port"], version, xid
            ))

    print(json.dumps({
        "purpose": "Direct ONC RPC NULL-procedure characterization of the task-reported status program 100024.",
        "program": PROGRAM,
        "procedure": 0,
        "versions_tested": list(VERSIONS),
        "timeout_seconds_per_probe": TIMEOUT_SECONDS,
        "observations": observations,
        "coverage_limitations": [
            "Only the two supplied hosts, their supplied TCP/UDP ports, program 100024, and versions 1 through 4 were queried.",
            "A NULL procedure reply characterizes RPC protocol behavior; it does not enumerate other RPC programs or procedures.",
            "No response is limited to this probe and timeout; it does not establish that the port or service is absent.",
            "RPC status behavior alone does not establish a credential-based or otherwise login-capable service."
        ],
        "login_capable_candidate_assessment": "not_established_by_null_procedure_probes"
    }, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
